BEGIN;

-- Ficha de Fausto Rey.
--
-- Fecha de nacimiento: se mantiene 1 de diciembre de 1951 (texto de Wikipedia es
-- y en, Vanguardia del Pueblo, Telefuturo). La ficha lateral de Wikipedia (es)
-- dice 6 de septiembre y Funglode da 1950.
--
-- occupations: se añade bandleader (dirigió «Fausto Rey y Orquesta», 1984-1986).
--
-- Sin premios: el Disco del Año de El Dorado por «El pájaro herido» solo aparece
-- en Wikipedia (en), que se apoya en el sitio del artista.
-- Fuera: padres, adopción y residencia (las fuentes se contradicen sobre dónde vive).

UPDATE artists SET occupations = '["composer","musician","bandleader"]'::jsonb WHERE slug = 'fausto-rey';

